static const char*gexpr(int i){return solverPlot?plotFields[i]:ys[i];}
static int gtype(int i){return solverPlot?plotTypes[i]:curveType[i];}
static int curveEval(int i,double t,double*out){return gtype(i)==0?evaluateXYZ(gexpr(i),t,0,0,ans,deg,1,out):gtype(i)==1?evaluateXYZ(gexpr(i),0,t,0,ans,deg,2,out):0;}
static int*activeShade(void){return solverPlot?plotShade:shadeSide;}
static int shadeCondition(int j,double x,double y,double*out){double v;if(gtype(j)==2)return equationValue(gexpr(j),x,y,0,ans,deg,out);if(!curveEval(j,gtype(j)?y:x,&v))return 0;*out=(gtype(j)?x:y)-v;return 1;}
static inline __attribute__((unused)) int shadeAt(double x,double y){int any=0;int*side=activeShade();for(int j=0;j<6;j++)if(side[j]&&*gexpr(j)){double diff;if(!shadeCondition(j,x,y,&diff))return 0;any=1;if(side[j]<0?diff>0:diff<0)return 0;}return any;}
static void drawShade(void){double cache[6][885];int*side=activeShade();int any=0;for(int j=0;j<6;j++)if(side[j]&&*gexpr(j)){any=1;if(gtype(j)<2){int len=gtype(j)?496:885;for(int i=0;i<len;i++){double t=gtype(j)?ymax-(ymax-ymin)*i/495:xmin+(xmax-xmin)*i/884,v;if(curveEval(j,t,&v))cache[j][i]=v;else cache[j][i]=NAN;}}}if(!any)return;color((SDL_Color){74,65,42,255});for(int row=0;row<496;row+=3){double y=ymax-(ymax-ymin)*row/495;int begin=-1;for(int col=0;col<=885;col+=3){int inside=col<885;double x=xmin+(xmax-xmin)*col/884;if(inside)for(int j=0;j<6;j++)if(side[j]&&*gexpr(j)){double diff;if(gtype(j)==2){if(!shadeCondition(j,x,y,&diff))diff=NAN;}else{double v=cache[j][gtype(j)?row:col];diff=(gtype(j)?x:y)-v;}if(!isfinite(diff)||(side[j]<0?diff>0:diff<0)){inside=0;break;}}if(inside&&begin<0)begin=col;if(!inside&&begin>=0){SDL_Rect b={70+begin,140+row,col-begin,3};pSDL_RenderFillRect(rr,&b);begin=-1;}}}}
static void traceCaption(char*out,size_t size){char formula[2048];const char*label=solverPlot&&*plotLabels[target]?plotLabels[target]:gexpr(target);pretty(label,formula,sizeof(formula));snprintf(out,size,"TRACE F%d: %s%s",target+1,solverPlot&&*plotLabels[target]?"":gtype(target)==0?"Y=":gtype(target)==1?"X=":"",formula);}
static void implicitCurve(int j){enum{NX=74,NY=42};double prev[NX+1],next[NX+1];for(int i=0;i<=NX;i++){double x=xmin+(xmax-xmin)*i/NX;if(!equationValue(gexpr(j),x,ymax,0,ans,deg,&prev[i]))prev[i]=NAN;}color(colors[j]);for(int row=1;row<=NY;row++){double y=ymax-(ymax-ymin)*row/NY;for(int i=0;i<=NX;i++){double x=xmin+(xmax-xmin)*i/NX;if(!equationValue(gexpr(j),x,y,0,ans,deg,&next[i]))next[i]=NAN;}for(int i=0;i<NX;i++){double v[]={prev[i],prev[i+1],next[i+1],next[i]};double xx[]={70+884.*i/NX,70+884.*(i+1)/NX,70+884.*(i+1)/NX,70+884.*i/NX},yy[]={140+495.*(row-1)/NY,140+495.*(row-1)/NY,140+495.*row/NY,140+495.*row/NY},sx[4],sy[4];int n=0;for(int e=0;e<4;e++){int k=(e+1)%4;if(isfinite(v[e])&&isfinite(v[k])&&v[e]!=v[k]&&(v[e]==0||v[k]==0||signbit(v[e])!=signbit(v[k]))){double t=v[e]/(v[e]-v[k]);sx[n]=xx[e]+t*(xx[k]-xx[e]);sy[n++]=yy[e]+t*(yy[k]-yy[e]);}}for(int k=0;k+1<n;k+=2)lineSDL(rr,sx[k],sy[k],sx[k+1],sy[k+1]);}memcpy(prev,next,sizeof(prev));}}
static void graph(void){rect(70,140,885,496,(SDL_Color){22,34,48,255});drawShade();color((SDL_Color){45,58,72,255});for(int i=0;i<=10;i++){lineSDL(rr,70+i*884/10,140,70+i*884/10,635);lineSDL(rr,70,140+i*495/10,954,140+i*495/10);}color(MUTED);if(xmin<=0&&xmax>=0)lineSDL(rr,px(0),140,px(0),635);if(ymin<=0&&ymax>=0)lineSDL(rr,70,py(0),954,py(0));
 for(int j=0;j<6;j++){if(!*gexpr(j))continue;if(gtype(j)==2){implicitCurve(j);continue;}color(colors[j]);int len=gtype(j)?495:884,prev=0,last=0;double lastv=0;for(int i=0;i<=len;i++){double t=gtype(j)?ymax-(ymax-ymin)*i/len:xmin+(xmax-xmin)*i/len,v;int ok=curveEval(j,t,&v)&&v>=(gtype(j)?xmin:ymin)&&v<=(gtype(j)?xmax:ymax);if(ok){int p=gtype(j)?px(v):py(v);double mid,step=(gtype(j)?-(ymax-ymin):xmax-xmin)/len;int continuous=prev&&abs(p-last)<200&&curveEval(j,t-step/2,&mid)&&fabs(mid-(v+lastv)/2)<(gtype(j)?xmax-xmin:ymax-ymin)*.1;if(continuous){if(gtype(j))lineSDL(rr,last,139+i,p,140+i);else lineSDL(rr,69+i,last,70+i,p);}else rect(gtype(j)?p:70+i,gtype(j)?140+i:p,2,2,colors[j]);last=p;lastv=v;}prev=ok;}}
 if(trace&&gtype(target)<2){double lo=gtype(target)?ymin:xmin,hi=gtype(target)?ymax:xmax;tx=fmax(lo,fmin(hi,tx));color(WHITE);if(gtype(target))lineSDL(rr,70,py(tx),954,py(tx));else lineSDL(rr,px(tx),140,px(tx),635);double v;char b[120];if(curveEval(target,tx,&v)){char tvalue[40],fvalue[40];numberText(tx,tvalue,sizeof(tvalue));numberText(v,fvalue,sizeof(fvalue));snprintf(b,sizeof(b),gtype(target)?"TRACE F%d   Y=%s   X=%s":"TRACE F%d   X=%s   Y=%s",target+1,tvalue,fvalue);}else snprintf(b,sizeof(b),tr("TRACE F%d · valor indefinido","TRACE F%d · undefined value"),target+1);text84(b,70,647,small,WHITE);}
 if(solverPlot)for(int i=0;i<markerCount;i++)if(markerX[i]>=xmin&&markerX[i]<=xmax&&markerY[i]>=ymin&&markerY[i]<=ymax){int x=px(markerX[i]),y=py(markerY[i]);color(colors[3]);lineSDL(rr,x-5,y,x+5,y);lineSDL(rr,x,y-5,x,y+5);rect(x-2,y-2,5,5,colors[3]);}
 char caption[2200];traceCaption(caption,sizeof(caption));if(strlen(caption)>74){int cut=71;while(((unsigned char)caption[cut]&192)==128)cut--;strcpy(caption+cut,"...");}text84(caption,70,68,(void*)(intptr_t)20,colors[target]);char b[160];snprintf(b,sizeof(b),"X:[%.4g,%.4g] Y:[%.4g,%.4g] F%d%s",xmin,xmax,ymin,ymax,target+1,solverPlot?" · SOLVER":"");text84(b,70,99,small,MUTED);}
